export const CL_CATS = [{"id":"cat-01","zh":"木材与木制品","en":"Timber & Wood Products","introZh":"所有木材及植物源性材料均受生物安全管控。处理须在离岸前由 DAFF 认可的服务商完成，并出具合规证书。熏蒸证书须符合《溴甲烷熏蒸方法 3.0 版》（2025 年 7 月 1 日起执行）的要求。","introEn":"Biosecurity controls apply to all wood and plant-derived material. Treatment must be completed offshore by a DAFF-recognised provider and evidenced by a compliant certificate. Fumigation certificates must meet the requirements of Methyl Bromide Fumigation Methodology v3.0 (effective 1 July 2025)."},{"id":"cat-02","zh":"石材与人造石","en":"Stone & Engineered Stone","introZh":"适用两套独立体系：天然及水泥基产品须进行石棉核查；含结晶二氧化硅达到或超过 1% 的人造石则被永久禁止进口。","introEn":"Two distinct regimes apply: asbestos verification for natural and cement-based products, and a permanent import prohibition on engineered stone containing crystalline silica at or above 1%."},{"id":"cat-03","zh":"建筑材料","en":"Building Materials","introZh":"本类别同时适用石棉核查、澳洲标准认证，铝合金门窗还涉及现行贸易救济措施。","introEn":"Asbestos verification, Australian Standards certification and — for aluminium windows and doors — active trade remedy measures all apply within this category."},{"id":"cat-04","zh":"家电与制冷设备","en":"Appliances & Refrigeration","introZh":"制冷剂种类与充注量是决定性因素。多种常见制冷剂已被禁止用于新设备进口。","introEn":"Refrigerant gas type and charge quantity are the controlling factors. Several common refrigerants are prohibited for import in new equipment."},{"id":"cat-05","zh":"车辆与机械设备","en":"Vehicles & Machinery","introZh":"道路车辆审批、发动机排放认证与生物安全清洁是三项独立且叠加的义务 —— 满足其中一项并不代表满足其余两项。","introEn":"Road vehicle approval, engine emissions certification and biosecurity cleanliness are three separate, cumulative obligations — clearing one does not satisfy the others."},{"id":"cat-06","zh":"预制建筑","en":"Prefabricated Buildings","introZh":"预制结构在单批货物中叠加多个风险品类 —— 木材、人造石、含石棉组件及制冷剂气体均须逐一处理。","introEn":"Prefab structures aggregate multiple risk categories in a single consignment — timber, engineered stone, asbestos-containing components and refrigerant gases must all be addressed."},{"id":"cat-07","zh":"农业用品","en":"Agricultural Products & Inputs","introZh":"植物与动物源性材料承担最高的生物安全义务。曾在田间使用过的农业机械须在发运前取得许可并完成清洁。","introEn":"Plant and animal derived materials carry the highest biosecurity burden. Agricultural machinery that has been used in the field requires pre-shipment licensing and cleaning."},{"id":"cat-08","zh":"电气与电子产品","en":"Electrical & Electronic Products","introZh":"所有投放澳洲市场的电气与电子产品均须完成 RCM 认证。注册须由澳大利亚本地法人实体持有。","introEn":"The RCM is mandatory for all electrical and electronic goods placed on the Australian market. Registration must be held by an Australian legal entity."},{"id":"cat-09","zh":"儿童用品","en":"Children's Products","introZh":"ACCC 强制安全标准适用于玩具、含纽扣电池产品及水上玩具。合规责任由进口商、制造商与零售商共同承担。","introEn":"ACCC mandatory safety standards apply to toys, button battery products and aquatic toys. Compliance is the responsibility of the importer, manufacturer and retailer."},{"id":"cat-10","zh":"化学品与危险品","en":"Chemicals & Dangerous Goods","introZh":"安全数据表、GHS 分类及 AICIS 注册义务适用于工业与危险化学品。两套制度均于 2025 年更新。","introEn":"Safety Data Sheets, GHS classification and AICIS registration obligations apply to industrial and hazardous chemicals. Both regimes were updated in 2025."},{"id":"cat-11","zh":"其他与交叉措施","en":"Other & Cross-Cutting Measures","introZh":"临时进出口及季节性 BMSB 措施适用独立框架，各有不同的文件要求。","introEn":"Temporary admissions and the seasonal BMSB regime operate under separate frameworks with distinct documentation requirements."},{"id":"cat-12","zh":"官方入口目录","en":"Official Portal Directory","introZh":"每项要求对应的官方权威来源。发运前请务必对照实时系统核查 —— 本指南仅供参考。","introEn":"The authoritative government source for each requirement. Always verify against the live portal before shipment — published guidance is indicative only."}];
